{
  "research": [
    {
      "id": "R1",
      "title": "Occlusion-Aware Feature Aggregation for Object Detection",
      "bullets": [
        "Formulated whether visible-region consistency could improve detection under partial occlusion; led development of a feature aggregation module using spatial confidence weights.",
        "Evaluated controlled occlusion patterns against standard detection baselines, using component ablations and localization error analysis to examine failure cases."
      ]
    },
    {
      "id": "R2",
      "title": "Illumination-Robust Self-Supervised Depth Estimation",
      "bullets": [
        "Investigated how illumination changes distort photometric supervision and led development of a depth training objective combining feature consistency with exposure-aware masking.",
        "Compared alternative masking criteria under synthetic lighting shifts, examining depth discontinuities, textureless surfaces, and sensitivity to photometric augmentation."
      ]
    },
    {
      "id": "R3",
      "title": "Cross-View Consistency for Weakly Supervised Semantic Segmentation",
      "bullets": [
        "Formulated how agreement across transformed views could refine segmentation from image labels; led development of confidence-weighted pseudo-label fusion and consistency training.",
        "Designed ablations separating localization cues, pseudo-label filtering, and boundary regularization; analyzed class confusion and foreground coverage across training stages."
      ]
    }
  ],
  "publications": [
    {
      "id": "P1",
      "title": "Confidence-Weighted Cross-View Pseudo-Label Fusion for Weakly Supervised Semantic Segmentation"
    },
    {
      "id": "P2",
      "title": "Foreground Coverage and Boundary Errors in Cross-View Weakly Supervised Segmentation"
    }
  ],
  "work": [
    {
      "id": "W1",
      "title": "Image Processing Service Maintenance",
      "bullets": [
        "Implemented image validation, resizing, and metadata extraction within an existing processing service, following established interface specifications and error-handling conventions.",
        "Maintained regression tests for malformed uploads and format conversions, investigated processing failures, and documented fixes for operational handoffs."
      ]
    }
  ],
  "projects": [
    {
      "id": "T1",
      "title": "Comparative Image Classification with Limited Training Data",
      "bullets": [
        "Implemented convolutional classification baselines and pretrained feature extraction, using consistent data splits and augmentation settings for comparative evaluation.",
        "Compared training from scratch with classifier-only adaptation and full fine-tuning, inspecting learning curves and class-level errors under limited supervision."
      ]
    },
    {
      "id": "T2",
      "title": "Stereo Matching Under Texture and Occlusion Challenges",
      "bullets": [
        "Implemented block matching and semi-global matching for rectified stereo images, including disparity consistency checks and invalid-pixel handling.",
        "Compared disparity errors across textured, textureless, and occluded regions, examining how matching costs and smoothness penalties affected reconstruction artifacts."
      ]
    },
    {
      "id": "T3",
      "title": "Motion and Appearance Cues for Multi-Object Tracking",
      "bullets": [
        "Implemented tracking baselines combining motion prediction with assignment-based association, then added appearance features within the same detection-driven pipeline.",
        "Compared association strategies on crowded sequences, analyzing identity switches, fragmented trajectories, and recovery after temporary occlusion using shared detections."
      ]
    },
    {
      "id": "T4",
      "title": "Confidence Calibration for Image Classification Under Corruption",
      "bullets": [
        "Implemented temperature scaling and histogram binning for image classifiers, fitting calibration parameters on held-out predictions without changing classifier weights.",
        "Compared calibration error and predictive accuracy across blur, noise, and contrast corruptions, examining reliability diagrams and sensitivity to validation distribution."
      ]
    }
  ]
}
